// scripts/generate-monetique-questions.js
const fs = require("fs");
const path = require("path");

const allQuestions = [];

function addQ(level, idNum, q, opts, ans, exp, trap) {
  allQuestions.push({
    id: `m_ex_n${level}_${String(idNum).padStart(2, "0")}`,
    gradeLevel: level,
    question: q,
    options: opts,
    correctIndex: ans,
    explanation: exp,
    trapWarning: trap
  });
}

// -------------------------------------------------------------
// NIVEAU 1 : FONDAMENTAUX & ISO 8583 (30 Questions)
// -------------------------------------------------------------
addQ(1, 1, "Dans le modèle des 4 coins du paiement par carte, qui tient le compte du porteur et valide la provision ?", ["L'Acquéreur", "L'Émetteur (Issuer)", "Le Switch / Scheme", "Le Commerçant"], 1, "L'émetteur tient le compte du porteur et valide l'autorisation de débit.", "Ne confondez pas avec l'acquéreur qui gère le terminal commerçant.");
addQ(1, 2, "Que signifie l'acronyme MTI dans la norme internationale ISO 8583 ?", ["Master Transaction Index", "Message Type Identifier", "Monetary Transfer Instruction", "Multiple Terminal Interface"], 1, "Le MTI identifie la classe, la fonction et l'origine du message financier.", "C'est l'identifiant de message à 4 chiffres en tête de chaque trame.");
addQ(1, 3, "Dans un MTI 0200, que signifie le premier chiffre '0' ?", ["Version ISO 8583:1987", "Transaction rejetée", "Message émis par un GAB", "Priorité réseau haute"], 0, "Le chiffre 0 indique la version originelle ISO 8583:1987. 1 désigne la version 1993 et 2 la version 2003.", "Ce n'est pas un code de statut mais le numéro de version de la norme.");
addQ(1, 4, "Dans un MTI 0200, que signifie le deuxième chiffre '2' ?", ["Message de réconciliation", "Message financier d'autorisation de débit", "Message de gestion de clé HSM", "Message de reversal"], 1, "La classe 2 désigne les messages financiers (Financial Transaction) avec engagement immédiat de fonds.", "La classe 1 désigne les autorisations pures d'engagement différé.");
addQ(1, 5, "Dans un MTI 0210, que signifie le troisième chiffre '1' ?", ["Demande initiale", "Réponse à une demande", "Avis d'information (Advice)", "Accusé de réception réseau"], 1, "La fonction 0 correspond à une Demande (Request) et la fonction 1 à une Réponse (Response).", "0210 est la réponse émetteur à la demande financière 0200.");
addQ(1, 6, "Comment détecte-t-on la présence d'un Bitmap secondaire (champs 65 à 128) dans une trame ISO ?", ["Le MTI se termine par 2", "Le premier bit du Bitmap primaire est positionné à 1", "Le champ DE1 est renseigné avec FF", "Le switch envoie une seconde trame"], 1, "Le bit 1 du bitmap primaire est le drapeau d'extension indiquant la présence du champ 1 (Bitmap secondaire).", "Si le bit 1 est à 0, seuls les champs 2 à 64 peuvent exister.");
addQ(1, 7, "Combien de champs au maximum un Bitmap primaire seul peut-il indexer ?", ["32 champs", "64 champs", "128 champs", "192 champs"], 1, "Le bitmap primaire comporte 64 bits (16 caractères hexadécimaux), indexant les champs de 1 à 64.", "Sans bitmap secondaire, le champ 65 et au-delà ne peuvent pas être encodés.");
addQ(1, 8, "Quel est le rôle du champ DE2 dans la norme ISO 8583 ?", ["Code devise", "Numéro de compte principal de la carte (PAN)", "Montant de la transaction", "Code réponse DE39"], 1, "DE2 contient le PAN (Primary Account Number) du porteur de la carte.", "DE2 est un champ de longueur variable de type LLVAR.");
addQ(1, 9, "Que signifie le type de format LLVAR pour un champ de données ISO 8583 ?", ["Longueur fixe de 2 chiffres", "Champ variable précédé de 2 chiffres indiquant sa longueur exacte", "Champ chiffré sur 2 octets", "Champ réservé à l'acquisition locale"], 1, "LLVAR indique que les 2 premiers caractères définissent la taille de la valeur qui suit (ex: 16 pour un PAN de 16 chiffres).", "LLLVAR utilise 3 chiffres d'en-tête pour les champs longs comme DE55.");
addQ(1, 10, "Quelle donnée fondamentale est transportée dans le champ DE4 ?", ["Date d'expiration", "Montant de la transaction en centimes", "Numéro de terminal TID", "STAN de l'opération"], 1, "DE4 transporte le montant financier de la transaction (Amount, Transaction) codé en 12 chiffres.", "Le montant est exprimé en unités minimales (centimes) sans séparateur décimal.");
addQ(1, 11, "Dans quel format le champ DE4 exprime-t-il un montant de 25 000 FCFA ?", ["25000", "000002500000", "250.00", "25000XOF"], 1, "DE4 est un numérique fixe n12 complété par des zéros à gauche (000002500000 pour 25 000.00).", "Ne mettez jamais de virgule ou de point dans un champ n12.");
addQ(1, 12, "Quel champ ISO 8583 contient le STAN (Systems Trace Audit Number) ?", ["DE3", "DE11", "DE37", "DE41"], 1, "DE11 est le STAN, un numéro de séquence à 6 chiffres unique par terminal et par jour.", "Ne confondez pas le STAN (DE11, 6 chiffres) avec le RRN (DE37, 12 caractères).");
addQ(1, 13, "Quelle est la différence fondamentale entre le STAN (DE11) et le RRN (DE37) ?", ["Le STAN est généré par le commerçant et le RRN par le porteur", "Le STAN est un compteur court local (6 chiffres) alors que le RRN est la référence globale unique de bout en bout (12 caractères)", "Le RRN est réservé aux cartes de crédit", "Il n'y a aucune différence"], 1, "Le STAN identifie la transaction au niveau du terminal, le RRN (Retrieval Reference Number) sert au rapprochement sur tout le réseau.", "Le RRN est souvent construit à partir de la date julienne et du STAN.");
addQ(1, 14, "Quel code réponse DE39 signale une transaction approuvée avec succès ?", ["01", "00", "99", "OK"], 1, "Le code 00 est le standard universel de l'approbation en monétique.", "Tout code différent de 00 (ou 08/10 selon les schemes) constitue un rejet.");
addQ(1, 15, "Que signifie le code rejet DE39 = 51 émis par la banque émettrice ?", ["Code PIN erroné", "Provision ou solde insuffisant", "Carte déclarée perdue ou volée", "Émetteur non disponible"], 1, "Le code 51 (Insufficient funds) indique que le compte du client ne dispose pas des fonds nécessaires.", "Le code 55 indique un problème de code PIN.");
addQ(1, 16, "Quel code DE39 signale qu'un client a composé un faux code secret au clavier ?", ["DE39 = 51", "DE39 = 55", "DE39 = 75", "DE39 = 54"], 1, "Le code 55 (Incorrect PIN) est retourné lorsque le cryptogramme de PIN ne correspond pas.", "Le code 75 est renvoyé lorsque le plafond d'essais de PIN (3 fois) est dépassé.");
addQ(1, 17, "Quel code DE39 indique que la date d'expiration de la carte est dépassée ?", ["DE39 = 54", "DE39 = 33", "DE39 = 41", "DE39 = 57"], 0, "Le code 54 (Expired card) est retourné lorsque la date du jour est postérieure au champ DE14.", "Le code 41 correspond à une carte volée déclarée en opposition.");
addQ(1, 18, "Que signale un pic soudain de rejets DE39 = 91 sur la console de supervision monétique ?", ["Une vague soudaine de fraudes par cartes perdues", "L'indisponibilité technique ou coupure de liaison avec le serveur émetteur", "Une panne mécanique des imprimantes GAB", "Une saturation de l'espace disque du TPE"], 1, "Le code 91 (Issuer or switch inoperative) traduit une rupture de connectivité ou un crash du serveur émetteur.", "C'est une alerte technique P1 d'infrastructure, pas un rejet commercial client.");
addQ(1, 19, "Quel champ ISO 8583 transporte le code devise de la transaction (ex: 952 pour XOF) ?", ["DE48", "DE49", "DE52", "DE4"], 1, "DE49 (Currency Code, Transaction) définit la devise selon la norme ISO 4217 (3 chiffres).", "DE50 peut transporter la devise de compensation (Settlement).");
addQ(1, 20, "Dans une trame ISO, quel champ contient le Terminal ID (TID) à 8 caractères ?", ["DE32", "DE41", "DE42", "DE43"], 1, "DE41 identifie le terminal physique (Card Acceptor Terminal Identification).", "DE42 est l'identifiant du commerçant (Merchant ID / Acceptor ID).");
addQ(1, 21, "Quel champ ISO transporte le Merchant ID (MID) ou identifiant commerçant ?", ["DE41", "DE42", "DE43", "DE25"], 1, "DE42 (Card Acceptor Identification Code) identifie le contrat commerçant auprès de l'acquéreur.", "DE43 contient le nom et la ville de l'enseigne commerciale.");
addQ(1, 22, "Que contient le champ DE3 (Processing Code) d'une trame ISO 8583 ?", ["Le numéro de licence du switch", "Un code à 6 chiffres précisant le type d'opération et les types de comptes débités/crédités", "Le numéro de série de la puce", "Le code postal du porteur"], 1, "Le Processing Code (ex: 000000 pour Achat, 010000 pour Retrait) structure le type d'opération.", "Les 2 premiers chiffres donnent l'opération, les 2 suivants le compte débité, les 2 derniers le compte crédité.");
addQ(1, 23, "Quel Processing Code (DE3) correspond typiquement à un retrait d'espèces sur compte courant au GAB ?", ["000000", "010000 (ou 011000)", "200000", "310000"], 1, "01 désigne un Cash Withdrawal (retrait). 00 désigne un Goods and Services (achat).", "31 désigne généralement une demande de solde (Balance Inquiry).");
addQ(1, 24, "Quel Processing Code (DE3) est couramment affecté à une consultation de solde au distributeur ?", ["000000", "300000 ou 310000", "010000", "200000"], 1, "Les codes commençant par 30 ou 31 sont réservés aux demandes d'information de compte sans débit.", "Une consultation de solde ne modifie pas le solde comptable du porteur.");
addQ(1, 25, "Quelle est la fonction d'un message de classe MTI 0800 / 0810 ?", ["Annuler un débit client", "Gérer la liaison réseau et tester l'écho (Network Management / Echo Test)", "Transférer un fichier de clearing", "Émettre un virement interbancaire"], 1, "La classe 8 (0800/0810) gère la signalisation réseau : Heartbeat (Echo Test), Logon, Logoff et échange de clés.", "Aucun mouvement financier client ne transite dans un message 0800.");
addQ(1, 26, "Pourquoi une trame d'Echo Test 0800 est-elle transmise périodiquement entre le switch et la banque ?", ["Pour vérifier que le canal télécom est actif et prévenir la fermeture des sockets TCP", "Pour synchroniser les taux de change du jour", "Pour archiver les journaux comptables", "Pour redémarrer les terminaux TPE"], 0, "L'Echo Test (généralement toutes les 60 secondes) garantit la détection immédiate d'une coupure de lien.", "L'absence de réponse 0810 après 3 envois consécutifs déclare le lien INACTIF.");
addQ(1, 27, "Quel code réseau (DE70) identifie un Echo Test standard ?", ["001", "301", "101", "201"], 1, "Le code 301 dans le champ DE70 signale universellement un Echo Test.", "Le code 001 désigne généralement un Logon et 002 un Logoff.");
addQ(1, 28, "Que contiennent les champs DE12 et DE13 dans une trame d'autorisation ?", ["Le code confidentiel PIN chiffré", "L'heure locale (DE12: hhmmss) et la date locale (DE13: MMDD) de la transaction sur le terminal", "Le solde restant du client", "Le numéro de téléphone du porteur"], 1, "DE12 transporte Time, Local (6 chiffres) et DE13 Date, Local (4 chiffres).", "DE7 transporte quant à lui la date et l'heure de transmission UTC.");
addQ(1, 29, "Quelle formule mathématique permet de valider la conformité d'un numéro de carte PAN ?", ["L'algorithme de Diffie-Hellman", "L'algorithme de Luhn (formule Modulo 10)", "Le hachage SHA-256", "Le chiffrement RSA"], 1, "La formule de Luhn (doublement alterné des chiffres et somme modulo 10) contrôle la validité du PAN.", "Le dernier chiffre du PAN est la clé de contrôle de Luhn.");
addQ(1, 30, "Pourquoi le stockage du cryptogramme CVV2 / CVC2 est-il strictement interdit après autorisation par PCI-DSS ?", ["Pour économiser de la place sur les disques durs", "Pour empêcher qu'une fuite de base de données ne permette d'effectuer des achats frauduleux sur Internet", "Parce que le CVV2 change toutes les 10 minutes", "Parce que le SGBD ne supporte pas les champs à 3 chiffres"], 1, "Le CVV2 au dos de la carte sert de preuve de possession physique : s'il était stocké en base, tout vol de données permettrait la fraude en ligne.", "C'est une exigence absolue de sécurité mondiale (PCI-DSS Requirement 3.2).");

// -------------------------------------------------------------
// NIVEAU 2 : TERMINAUX BANCAIRES & PROTOCOLES (30 Questions)
// -------------------------------------------------------------
addQ(2, 1, "Quel protocole est très largement utilisé pour piloter la couche applicative des distributeurs NCR ?", ["NDC+ (NCR Direct Connect)", "HTTP/REST", "Modbus", "SNMP v3"], 0, "NDC+ et DDC sont les deux protocoles maîtres de communication entre les GAB et le serveur concentrateur.", "Ces protocoles définissent les états de cassettes, les séquences d'affichage et les ordres de distribution.");
addQ(2, 2, "Dans un GAB, quel composant mécanique prélève physiquement les billets dans les cassettes de stockage ?", ["Le Card Reader", "Le Pick Module (Pick mechanism)", "Le Thermal Printer", "L'Encrypting PIN Pad (EPP)"], 1, "Le module de prise (Pick) aspire ou saisit les coupures une par une pour les empiler dans le stacker.", "L'EPP sert uniquement à la saisie sécurisée du code PIN.");
addQ(2, 3, "À quoi sert le capteur de double épaisseur (Double Detect / Thickness Sensor) dans un distributeur de billets ?", ["À compter le nombre de personnes devant le GAB", "À détecter si deux billets sont collés afin de les rejeter dans le bac de purge (Diverter Cassette)", "À mesurer le poids du coffre-fort", "À vérifier l'authenticité de la puce"], 1, "Si deux billets sont collés, le capteur les déroute immédiatement vers la cassette de rejet sans les donner au client.", "Cela évite de distribuer le double du montant demandé par le porteur.");
addQ(2, 4, "Que signifie l'état 'SHUTTER CLOSED' dans le journal électronique (ATM EJ) après un incident matériel ?", ["L'automate a fermé l'agence bancaire", "Le volet mécanique de distribution est resté fermé, prouvant que les billets n'ont pas été présentés à l'extérieur", "La caméra de surveillance s'est éteinte", "Le clavier PIN pad est désactivé"], 1, "SHUTTER CLOSED est la preuve juridique formelle que les billets n'ont jamais franchi la façade de l'automate.", "C'est l'élément déterminant pour statuer en faveur d'un recrédit porteur.");
addQ(2, 5, "Quel MTI ISO 8583 identifie un avis d'annulation (Reversal Advice) généré automatiquement par un automate ?", ["0100", "0420", "0210", "0800"], 1, "0420 est le message d'avis d'annulation envoyé lorsque le terminal n'a pas pu achever la transaction approuvée.", "0400 est la demande d'annulation, 0420 l'avis avec mécanisme de répétition SAF.");
addQ(2, 6, "Pourquoi un Reversal (0420) doit-il impérativement transporter le champ DE90 ?", ["Pour indiquer le numéro de téléphone de l'agence", "Pour contenir les données d'origine de la transaction à annuler (MTI originel, STAN, Date, Acquirer ID)", "Pour chiffrer à nouveau le code PIN", "Pour imprimer un coupon promotionnel"], 1, "Le champ DE90 (Original Data Elements) permet à l'émetteur de retrouver avec certitude l'autorisation d'origine à contrepasser.", "Sans DE90 valide, le système émetteur rejette l'annulation avec le code 25 (Unable to locate record).");
addQ(2, 7, "Combien de temps dure généralement le time-out d'attente d'autorisation sur un TPE ou GAB ?", ["2 secondes", "25 à 30 secondes", "5 minutes", "24 heures"], 1, "Le standard de l'industrie bancaire fixe le time-out acquéreur entre 25 et 30 secondes maximum.", "Au-delà de ce délai, le client ne peut pas rester bloqué et le terminal bascule en time-out.");
addQ(2, 8, "Si la banque émettrice répond avec succès (DE39=00) au bout de 40 secondes, que fait le terminal ?", ["Il distribue quand même l'argent", "Il a déjà expiré son time-out, refuse l'opération et émet un Reversal 0420", "Il crédite le compte du commerçant deux fois", "Il capture la carte bancaire"], 1, "Le terminal ayant coupé l'attente à 30 secondes, la réponse tardive est ignorée et un 0420 est généré pour annuler le débit émetteur.", "C'est un cas classique de Late Response.");
addQ(2, 9, "Qu'est-ce qu'un débit fantôme (Ghost Debit) dans l'expérience d'un porteur de carte ?", ["Un débit effectué par un automate situé dans un cimetière", "Un débit débité sur le compte client alors que le distributeur ou le commerçant n'a pas remis les fonds ou la marchandise", "Une transaction effectuée avec une carte dont le titulaire est décédé", "Une taxe prélevée par la banque centrale"], 1, "Le débit fantôme survient lorsque l'émetteur a validé le débit mais que la confirmation finale ou la distribution a échoué sans Reversal.", "Le client voit son solde amputé alors qu'il n'a rien reçu.");
addQ(2, 10, "Quel mécanisme réseau garantit qu'une trame d'annulation 0420 finira par être reçue même si la liaison tombe momentanément ?", ["Le Store and Forward (SAF)", "Le protocole DHCP", "Le chiffrement RSA", "Le câble coaxial"], 0, "Le SAF stocke la trame d'annulation en file d'attente locale et la renvoie en boucle dès le rétablissement de la connexion.", "Le SAF évite toute perte de Reversal due aux coupures intermittentes.");
addQ(2, 11, "Dans un journal de GAB (ATM EJ), que signifie la mention 'NOTES TAKEN BY CUSTOMER' ?", ["Le client a refusé les billets", "Les capteurs optiques du volet ont validé le retrait effectif des billets par la main du client", "Le convoyeur de fonds a rechargé le coffre", "L'automate a avalé les coupures abîmées"], 1, "NOTES TAKEN atteste de la prise en main physique des billets par le client.", "Si un client prétend ne rien avoir reçu alors que l'EJ indique NOTES TAKEN, la réclamation est contestée.");
addQ(2, 12, "Dans un terminal de paiement électronique (TPE/POS), que désigne la procédure de 'Télécollecte' de fin de journée ?", ["La mise à jour de l'antivirus du terminal", "L'envoi groupé de toutes les transactions de la journée vers le serveur acquéreur pour déclencher le crédit du compte commerçant", "La vérification de l'imprimante ticket", "Le changement du code PIN du commerçant"], 1, "La télécollecte vide la mémoire du TPE et génère les écritures de crédit commerçant.", "Sans télécollecte, les fonds restent bloqués et ne sont pas versés au commerçant.");
addQ(2, 13, "Quel protocole international de messagerie POS standardise les échanges entre terminaux de paiement et serveurs acquéreurs ?", ["Protocole CB2A / Nexo Fast / AS 2805", "FTP", "POP3", "Telnet"], 0, "Nexo (basé sur ISO 20022) et CB2A sont les standards modernes d'acquisition commerçant.", "Ils remplacent les protocoles propriétaires par des messages XML/JSON ou ISO normalisés.");
addQ(2, 14, "Comment appelle-t-on le clavier ultra-sécurisé d'un distributeur ou TPE certifié pour la saisie du PIN ?", ["EPP (Encrypting PIN Pad)", "Keyboard QWERTY", "Touch screen standard", "Virtual keypad"], 0, "L'EPP est un boîtier blindé doté de micro-rupteurs qui détruisent les clés cryptographiques si quelqu'un tente de l'ouvrir.", "La norme PCI-PTS régit les spécifications physiques de l'EPP.");
addQ(2, 15, "Que se passe-t-il si un fraudeur tente de percer physiquement la coque d'un EPP certifié PCI-PTS ?", ["L'EPP prend une photo du voleur", "Les circuits de détection d'intrusion déclenchent l'effacement immédiat et irréversible de toutes les clés de sécurité en mémoire (Zeroization)", "L'EPP envoie un SMS à la police", "L'écran affiche une sirène rouge"], 1, "Le mécanisme de Zeroization efface les clés maîtresses en une fraction de milliseconde.", "Le HSM ou l'EPP devient alors totalement inutilisable (brique électronique).");
addQ(2, 16, "Dans un GAB, quelle est la fonction de la cassette de purge (Diverter / Purge Bin) ?", ["Stocker les billets neufs avant distribution", "Recueillir les billets jugés suspects, froissés, collés ou oubliés par le client dans le volet", "Garder les tickets de reçu non imprimés", "Collecter les cartes bancaires expirées"], 1, "La cassette Diverter accueille tous les billets qui n'ont pas pu être distribués dans des conditions parfaites.", "Son audit lors de la balance contradictoire de caisse permet de retrouver les billets manquants.");
addQ(2, 17, "Si un client met plus de 30 secondes à retirer ses billets présentés dans le volet du GAB, que fait l'automate ?", ["Il fait sonner une alarme sonore", "Il rétracte les billets dans la cassette de purge pour des raisons de sécurité publique (Retract)", "Il les brûle", "Il les donne au passant suivant"], 1, "Le mécanisme de Retract protège les fonds si le client a fait un malaise ou est parti en oubliant l'argent.", "L'événement est consigné dans l'EJ : BILLS RETRACTED TO PURGE BIN.");
addQ(2, 18, "Quelle est la différence entre une transaction en ligne (Online) et une transaction hors-ligne (Offline) sur un TPE ?", ["La transaction en ligne utilise le réseau mobile 4G et l'autre le Wi-Fi", "La transaction en ligne interroge en temps réel le serveur de la banque pour autorisation, alors que la transaction hors-ligne est approuvée par la puce de la carte seule", "La transaction hors-ligne n'utilise pas d'électricité", "La transaction en ligne ne demande jamais de code PIN"], 1, "En Offline, le TPE et la carte décident de la transaction sans connexion télécom (très utilisé dans les péages et transports).", "Le commerçant transmettra la transaction plus tard lors de la télécollecte.");
addQ(2, 19, "Sur quel critère principal un TPE décide-t-il d'envoyer une transaction en ligne plutôt que de l'approuver hors-ligne ?", ["La météo", "Le dépassement du plafond d'autorisation hors-ligne commerçant (Floor Limit) et les drapeaux de la puce carte", "L'heure de la journée uniquement", "La marque de l'écran du TPE"], 1, "Le Floor Limit est le montant maximum au-delà duquel toute transaction doit impérativement être vérifiée auprès de la banque.", "Si le montant > Floor Limit, le terminal force un appel en ligne.");
addQ(2, 20, "Quel MTI identifie un message d'avis financier (Financial Advice) confirmant une transaction déjà effectuée hors-ligne ?", ["0200", "0220", "0110", "0800"], 1, "Le MTI 0220 informe la banque d'une transaction qui a déjà eu lieu (Advice) et exige sa prise en compte comptable.", "La banque ne peut pas refuser un 0220, elle doit l'enregistrer.");
addQ(2, 21, "Que contient le champ DE38 dans une réponse d'autorisation approuvée (DE39=00) ?", ["Le numéro de compte IBAN du commerçant", "Le code d'autorisation (Approval Code / Auth Code) à 6 caractères alphanumériques", "Le montant des agios prélevés", "Le solde restant du client"], 1, "DE38 est le numéro d'autorisation officiel qui sera imprimé sur le ticket de caisse et figurera sur le relevé.", "Il certifie la réservation de la provision par la banque.");
addQ(2, 22, "Pourquoi les reçus commerçants masquent-ils obligatoirement une partie du PAN (ex: 4970 10** **** 7890) ?", ["Pour économiser l'encre de l'imprimante thermique", "Pour respecter la règle de masquage (PAN Truncation / Masking) imposée par PCI-DSS afin de protéger le porteur contre le vol de données", "Parce que les rouleaux de papier sont trop étroits", "Pour masquer la nationalité du client"], 1, "La règle de troncature n'autorise l'affichage que des 6 premiers chiffres (BIN) et des 4 derniers chiffres.", "Elle empêche les employés indélicats de collecter les numéros de carte sur les tickets abandonnés.");
addQ(2, 23, "Dans une liaison monétique, qu'est-ce que le protocole de couche basse AS 2805 ?", ["Une norme australienne dérivée de l'ISO 8583 très utilisée pour les liaisons directes TPE/GAB avec chiffrement point-à-point", "Un câble réseau en fibre de verre", "Un algorithme de hachage de mot de passe", "Un format de fichier de tableur"], 0, "AS 2805 est la norme de fait pour de nombreux réseaux de switch avec intégration native du chiffrement des champs sensibles.", "Elle s'apparente étroitement à l'ISO 8583 mais standardise le chiffrement de bout en bout.");
addQ(2, 24, "Que désigne l'acronyme POS dans le jargon monétique international ?", ["Point of Sale (Terminal de Paiement Électronique / TPE)", "Payment Operating System", "Private Online Server", "Postal Ordering Service"], 0, "POS (Point of Sale) désigne tout terminal de paiement électronique chez un marchand (physique ou mPOS).", "En français, on parle indifféremment de TPE ou de POS.");
addQ(2, 25, "Quelle action effectue un GAB lorsque le porteur oublie sa carte dans le lecteur pendant plus de 20 secondes après la restitution ?", ["Il l'éjecte sur le trottoir", "Il capture et avale physiquement la carte dans un bac dédié pour éviter qu'un tiers ne s'en empare", "Il annule toutes les opérations du mois", "Il imprime le code secret sur un ticket"], 1, "La capture de carte par temporisation protège le porteur contre le vol opportuniste.", "L'incident est noté dans l'EJ : 'CARD CAPTURED - RETENTION TIMEOUT'.");
addQ(2, 26, "Comment la banque acquéreuse détecte-t-elle qu'un GAB est victime d'une attaque par Cash Trapping (piège à billets) ?", ["Par l'augmentation soudaine de la température du coffre", "Par une succession anormale d'alertes de volet bloqué (Shutter Jam) sur des montants ronds et des réclamations clients concordantes", "Par la coupure du câble d'alimentation électrique", "Par la baisse du cours de la devise"], 1, "Le Cash Trapping consiste à coller une réglette adhésive sur le volet pour intercepter les billets.", "L'automate signale des anomalies mécaniques répétées sur le module Shutter.");
addQ(2, 27, "Qu'est-ce qu'une attaque de type 'Black Box' sur un automate bancaire GAB ?", ["Peindre le distributeur en noir pour masquer la caméra", "Connecter un appareil pirate directement sur le câble interne du distributeur de billets pour lui ordonner de vider les cassettes sans passer par le PC du GAB", "Voler le coffre-fort avec un camion bélier", "Introduire un faux billet dans le lecteur"], 1, "L'attaque Black Box pirate la liaison USB/Série entre le PC de l'automate et le coffre distributeur.", "Elle est neutralisée par le chiffrement fort des communications internes (TMD Security / Chiffrement bus XFS).");
addQ(2, 28, "Dans l'architecture logicielle d'un GAB, que désigne le standard CEN/XFS (Extensions for Financial Services) ?", ["Un système de ventilation pour le coffre-fort", "Une couche logicielle d'abstraction middleware standardisée permettant à une application bancaire de piloter n'importe quel matériel GAB (NCR, Diebold, Wincor)", "Un format de carte bancaire rectangulaire", "Un diplôme d'agent de sécurité"], 1, "XFS permet de développer un logiciel monétique unique compatible avec tous les constructeurs mondiaux d'automates.", "Le logiciel interagit avec des XFS Service Providers matériels.");
addQ(2, 29, "Lors d'une panne d'alimentation électrique brutale pendant la distribution de billets, que garantit la batterie de secours (onduleur UPS) du GAB ?", ["De continuer à faire fonctionner le distributeur pendant 24 heures", "D'achever proprement la séquence mécanique en cours, d'écrire le statut dans l'EJ et d'émettre la trame d'annulation ou de confirmation avant l'arrêt complet", "D'éclairer la rue", "De recharger les téléphones des clients"], 1, "L'onduleur donne les 2 minutes nécessaires pour garantir l'intégrité des écritures comptables et éviter les états mécaniques indéterminés.", "Sans onduleur, les coupures de courant génèrent des litiges de caisse insolubles.");
addQ(2, 30, "Que contient le champ DE18 d'une trame ISO 8583 (Merchant Category Code - MCC) ?", ["L'âge du commerçant", "Un code à 4 chiffres classifiant l'activité commerciale du point de vente (ex: 6011 pour GAB, 5411 pour Supermarchés)", "Le numéro de compte bancaire du commerçant", "Le code postal du siège social"], 1, "Le MCC (ex: 6011 GAB, 5812 Restaurants, 5541 Stations-service) sert au calcul des plafonds, à la détection de fraude et au barème d'interchange.", "Les banques émettrices bloquent certains MCC à risque (jeux en ligne, cryptomonnaies) selon leur politique.");

// -------------------------------------------------------------
// NIVEAU 3 : EMV, TLV & CRYPTOGRAMMES (30 Questions)
// -------------------------------------------------------------
addQ(3, 1, "Dans une trame ISO 8583, quel champ transporte l'ensemble des données de la puce EMV au format TLV ?", ["DE48", "DE52", "DE55", "DE120"], 2, "DE55 (Integrated Circuit Card Related Data) contient les tags EMV générés par la carte et le terminal.", "C'est un champ variable de type LLLVAR codé en hexadécimal.");
addQ(3, 2, "Que signifie la structure BER-TLV utilisée par la norme EMVCo ?", ["Binary Encrypted Routing - Terminal Link Verification", "Tag - Length - Value (Balise, Longueur, Valeur)", "Total Limit Volume", "Transaction Log Variable"], 1, "Le format TLV séquence les informations : le Tag identifie la donnée, la Longueur donne sa taille, la Valeur contient les octets utiles.", "Ce format permet d'ajouter des tags facultatifs sans casser la compatibilité descendante.");
addQ(3, 3, "Quel tag EMV correspond au cryptogramme applicatif (Application Cryptogram) généré par la puce ?", ["Tag 95", "Tag 9F26", "Tag 9F36", "Tag 82"], 1, "Le Tag 9F26 (8 octets) contient le cryptogramme de transaction (ARQC, TC ou AAC).", "Ce cryptogramme est validé en ligne par le HSM émetteur.");
addQ(3, 4, "Quel type de cryptogramme EMV est généré par la carte lorsqu'une autorisation en ligne est requise ?", ["TC (Transaction Certificate)", "ARQC (Authorization Request Cryptogram)", "AAC (Application Authentication Cryptogram)", "AAR (Application Authorization Referral)"], 1, "L'ARQC est envoyé à la banque pour demander son accord en ligne. Sa valeur est indiquée par le Tag 9F27 = 80.", "Si la banque approuve, elle renvoie un ARPC pour que la carte génère un TC.");
addQ(3, 5, "Quel cryptogramme EMV atteste que la transaction a été approuvée définitivement (hors-ligne ou après réponse positive) ?", ["TC (Transaction Certificate)", "ARQC", "AAC", "PIN"], 0, "Le TC (Transaction Certificate) est la preuve cryptographique irréfutable que la carte a validé le débit.", "Le TC sera transmis au clearing pour le règlement financier.");
addQ(3, 6, "Quel cryptogramme EMV est généré par la carte en cas de refus catégorique de la transaction ?", ["AAC (Application Authentication Cryptogram)", "ARQC", "TC", "CAP"], 0, "L'AAC prouve que la carte a rejeté l'opération (ex: PIN bloqué, plafond hors-ligne dépassé et refus de passer en ligne).", "L'AAC empêche le commerçant de forcer le paiement.");
addQ(3, 7, "Quel tag EMV contient le registre TVR (Terminal Verification Results) codé sur 5 octets ?", ["Tag 9F26", "Tag 95", "Tag 9B", "Tag 84"], 1, "Le Tag 95 contient le TVR, qui recense bit-à-bit tous les contrôles de sécurité exécutés par le terminal.", "Le Tag 9B contient le TSI (Transaction Status Information).");
addQ(3, 8, "Que contient le Tag 9F36 dans le bloc EMV DE55 ?", ["Le code secret en clair", "L'ATC (Application Transaction Counter), un compteur séquentiel incrémenté à chaque opération", "L'adresse IP du terminal", "Le montant en devise locale"], 1, "L'ATC est un compteur matériel interne à la puce qui ne peut jamais reculer.", "Il permet au HSM de dériver la clé de session unique de la transaction.");
addQ(3, 9, "Pourquoi le terminal génère-t-il un nombre aléatoire (Unpredictable Number - Tag 9F37) pour la puce ?", ["Pour amuser le porteur", "Pour injecter de l'aléa dans le calcul de l'ARQC et empêcher toute attaque par rejeu d'un ancien cryptogramme copié", "Pour choisir la langue du reçu", "Pour tester la vitesse du processeur"], 1, "L'Unpredictable Number garantit qu'un pirate ayant enregistré une transaction ne pourra jamais la réutiliser.", "C'est un pilier de la sécurité anti-clonage EMV.");
addQ(3, 10, "Dans le registre TVR (Tag 95), quel octet contient les résultats de la vérification du titulaire (CVM) ?", ["Octet 1", "Octet 2", "Octet 3", "Octet 5"], 1, "L'octet 2 du TVR recense les événements du CVM (ex: échec du PIN, PIN try limit exceeded).", "L'octet 1 est dédié à l'authentification des données hors-ligne (SDA/DDA/CDA).");
addQ(3, 11, "Si le bit 6 de l'octet 2 du TVR est à 1 (valeur hexadécimale '00 40 00 00 00'), quelle situation est survenue ?", ["La carte est périmée", "Le nombre maximum de tentatives de saisie de code PIN a été dépassé (PIN Try Limit Exceeded)", "Le commerçant est inconnu", "La batterie du terminal est faible"], 1, "Ce bit signale que le compteur de faux PIN a atteint son seuil d'épuisement (généralement 3 essais).", "La carte refuse désormais toute saisie de code PIN.");
addQ(3, 12, "Que signifie l'acronyme AID dans l'univers de la carte à puce EMV ?", ["Automatic Identification Device", "Application Identifier (Identifiant d'application sur la puce, ex: Visa A0000000031010)", "Account In Dispute", "Authorized Issuer Directory"], 1, "L'AID identifie l'application bancaire hébergée dans la puce (Visa Credit/Debit, Mastercard, GIM).", "Le terminal compare l'AID de la carte avec sa liste d'applications acceptées.");
addQ(3, 13, "Quelle méthode d'authentification de la puce repose sur une signature asymétrique RSA dynamique calculée à chaque transaction ?", ["SDA (Static Data Authentication)", "DDA (Dynamic Data Authentication)", "Piste 1 magnétique", "Code CVC"], 1, "La DDA utilise une paire de clés RSA interne à la puce pour signer dynamiquement les données, rendant le clonage impossible.", "La SDA plus ancienne ne protégeait pas contre le clonage parfait de puce.");
addQ(3, 14, "Qu'apporte la technologie CDA (Combined DDA/Application Cryptogram Generation) par rapport à la DDA classique ?", ["Elle permet de payer en bitcoins", "Elle combine la génération de l'ARQC/TC et la signature DDA en une seule commande APDU ultra-rapide", "Elle supprime le besoin de code PIN", "Elle double la limite de retrait"], 1, "La CDA accélère le paiement et protège contre les attaques de type 'Man-in-the-Middle' sur le bus de la puce.", "Elle est devenue obligatoire pour les cartes EMV sans contact (Contactless).");
addQ(3, 15, "Dans une transaction avec saisie du code PIN, qu'est-ce que le mode 'Offline PIN' ?", ["Le terminal envoie le PIN par SMS", "Le code PIN tapé au clavier est transmis directement à la puce de la carte qui le valide localement sans appel réseau", "Le commerçant note le PIN sur un calepin", "Le PIN est vérifié par satellite"], 1, "En Offline PIN (très répandu en Europe et sur les péages), la puce compare le code tapé avec sa valeur sécurisée interne.", "Si le code est bon, la puce répond '90 00' (Success).");
addQ(3, 16, "Qu'est-ce que le mode 'Online PIN' très utilisé dans les pays d'Afrique (GIM-UEMOA) et aux USA ?", ["Le porteur valide son achat sur son smartphone", "Le code PIN est chiffré dans l'EPP et transmis dans le champ DE52 de la trame ISO pour validation par le HSM émetteur", "Le commerçant appelle la banque au téléphone", "Le PIN n'est pas vérifié"], 1, "En Online PIN, la puce ne connaît pas le PIN : c'est le serveur bancaire central qui compare le PIN Block reçu.", "Le champ DE52 transporte le PIN Block chiffré sous ZPK.");
addQ(3, 17, "Que contient le Tag 82 dans le profil de la carte EMV ?", ["L'AIP (Application Interchange Profile), indiquant les capacités cryptographiques supportées par la carte", "Le solde bancaire en devises", "Le nom du porteur", "Le code guichet de l'agence"], 0, "L'AIP indique au terminal si la carte supporte la DDA, la CDA, l'Offline PIN ou la gestion des risques émetteur.", "Le terminal adapte son scénario en fonction des bits de l'AIP.");
addQ(3, 18, "Quelle réponse APDU ISO 7816 émise par la puce signale le succès d'une commande ?", ["00 00", "90 00", "FF FF", "OK 01"], 1, "Le statut '90 00' (SW1=90, SW2=00) est le code universel de succès des cartes à puce intelligentes.", "'6A 82' signifie fichier non trouvé, '69 84' données invalides.");
addQ(3, 19, "Quel cryptogramme la banque émettrice retourne-t-elle dans le Tag 91 de sa réponse 0210 pour prouver son authenticité à la carte ?", ["ARQC", "ARPC (Authorization Response Cryptogram)", "CVV2", "PIN Block"], 1, "L'ARPC prouve à la puce que la réponse vient bien de sa vraie banque émettrice et non d'un faux switch pirate.", "La puce vérifie l'ARPC avant de délivrer le TC final.");
addQ(3, 20, "Que permet le mécanisme de 'Script Processing' (Tags 71 et 72) renvoyé par la banque dans la réponse 0210 ?", ["Changer la couleur de l'écran du terminal", "Mettre à jour à distance la mémoire de la puce (débloquer un PIN, modifier les plafonds hors-ligne, bloquer l'application)", "Envoyer un e-mail au client", "Télécharger une sonnerie sur le TPE"], 1, "Les scripts émetteurs permettent d'administrer la carte en temps réel lors d'un paiement en ligne.", "C'est ainsi qu'un client débloque son code secret au distributeur après l'avoir réinitialisé en agence.");
addQ(3, 21, "Pourquoi la norme EMVCo a-t-elle introduit le mécanisme de 'Liability Shift' (Transfert de responsabilité) ?", ["Pour exonérer les banques de toute taxe", "Pour imposer financièrement le coût de la fraude à la partie (commerçant ou banque) qui n'a pas migré vers la puce EMV", "Pour transférer les dettes des clients à la banque centrale", "Pour supprimer les cartes magnétiques en une seule nuit"], 1, "Si un commerçant utilise encore la piste magnétique alors que la carte a une puce, il supporte 100% de la fraude.", "Ce principe a incité tous les commerçants de la planète à s'équiper de lecteurs de puce.");
addQ(3, 22, "Qu'est-ce qu'une transaction de repli (Fallback) en monétique EMV ?", ["Un paiement annulé par le client", "Une transaction où la puce étant illisible ou défectueuse, le terminal bascule sur la lecture de la piste magnétique", "Un achat payé en espèces", "Un virement différé"], 1, "Le Fallback dépanne un client dont la puce est rayée en lisant la piste magnétique.", "Les transactions en Fallback sont très surveillées car les fraudeurs rayent volontairement de fausses puces pour forcer la piste.");
addQ(3, 23, "Quel code dans le champ DE22 (Point of Service Entry Mode) signale une transaction réalisée par puce EMV sans contact (Contactless) ?", ["012", "071 ou 072", "021", "901"], 1, "Les valeurs '07' indiquent une lecture sans contact (NFC / Contactless). '05' indique une puce avec contact.", "'02' indique une lecture par piste magnétique.");
addQ(3, 24, "Dans une transaction sans contact, que signifie le mode 'EMV Contactless' par rapport au mode 'Magstripe Mode Contactless' ?", ["Le mode Magstripe simule une piste magnétique par ondes radio, tandis que le mode EMV génère un véritable cryptogramme ARQC dynamique", "Le mode Magstripe nécessite d'insérer la carte dans une fente", "Le mode EMV ne fonctionne qu'avec les téléphones Apple", "Il n'y a aucune différence technique"], 0, "Le mode Magstripe historique envoyait des données statiques peu sûres ; l'EMV sans contact moderne produit un cryptogramme dynamique complet.", "Tous les terminaux modernes exigent désormais le mode EMV sans contact.");
addQ(3, 25, "Que contient le Tag 5F24 dans les données de l'application de la carte ?", ["Le code postal de l'émetteur", "La date d'expiration de l'application (Application Expiration Date, format AAMMJJ)", "Le numéro de téléphone du service client", "Le solde autorisé du mois"], 1, "Le Tag 5F24 est comparé avec la date du jour du terminal (Tag 9A). Si 9A > 5F24, le bit 'Expired Application' est armé dans le TVR.", "Le terminal refuse l'opération ou force un appel en ligne.");
addQ(3, 26, "Dans le Tag 9F10 (Issuer Application Data), que trouve-t-on habituellement ?", ["Le nom des enfants du porteur", "Des données propriétaires de l'émetteur incluant le format de dérivation de clé, l'index de clé et les compteurs de fraude", "L'adresse de l'agence bancaire", "Le numéro de TVA du commerçant"], 1, "Le Tag 9F10 permet au système émetteur de savoir quelle clé maîtresse a servi à personnaliser la carte.", "Le HSM hôte l'utilise pour recalculer l'ARQC.");
addQ(3, 27, "Qu'est-ce que le CVM List (Cardholder Verification Method List - Tag 8E) d'une carte bancaire ?", ["La liste des magasins où la carte est interdite", "La liste ordonnée des méthodes de vérification d'identité acceptées par la carte (ex: 1. Offline PIN, 2. Online PIN, 3. Signature)", "La liste des pays où la carte fonctionne", "La liste des virements du mois"], 1, "La puce déroule sa CVM List pour négocier avec le terminal la méthode de validation la plus sûre possible.", "Si le terminal n'a pas de PIN pad, la puce passe à la méthode suivante (ex: signature papier).");
addQ(3, 28, "Dans le registre TSI (Transaction Status Information - Tag 9B sur 2 octets), que signifie le bit 8 de l'octet 1 à 1 ?", ["Le terminal a effectué l'authentification des données hors-ligne (Offline Data Authentication was performed)", "La carte a été volée", "Le reçu a été imprimé", "Le commerçant a refusé le paiement"], 0, "Le TSI documente quelles fonctions ont été réellement exécutées durant la transaction.", "Il complète le TVR qui documente les anomalies constatées.");
addQ(3, 29, "Pourquoi une carte bancaire EMV refuse-t-elle d'effectuer une transaction si le compteur de dérivation ATC saute de 1 000 numéros d'un coup ?", ["Elle pense que le porteur a changé de pays", "Elle suspecte une tentative d'attaque par clonage ou d'épuisement de compteurs et force une synchronisation en ligne", "Elle s'autodétruit", "Elle remet son solde à zéro"], 1, "Un saut d'ATC anormal est un indice fort d'attaque par sondage de puce ou d'utilisation d'un clone partiel.", "L'émetteur bloque immédiatement la carte.");
addQ(3, 30, "Quel tag EMV correspond au PAN Sequence Number (PSN) distinguant deux cartes ayant le même numéro de compte ?", ["Tag 5A", "Tag 5F34", "Tag 9F02", "Tag 84"], 1, "Le Tag 5F34 (PSN sur 1 octet, ex: 01, 02) différencie une carte réémise après perte de la carte précédente.", "Le PSN fait partie intégrante du calcul de dérivation de clé cryptographique dans le HSM.");

// -------------------------------------------------------------
// NIVEAU 4 : SÉCURITÉ & HSM (30 Questions)
// -------------------------------------------------------------
addQ(4, 1, "Quel est le rôle principal d'un boîtier HSM (Hardware Security Module) dans un système monétique ?", ["Accélérer l'affichage des pages web", "Sécuriser, stocker et manipuler les clés cryptographiques et les codes PIN dans un environnement matériel inviolable", "Sauvegarder les relevés de compte sur bande magnétique", "Remplacer le routeur Cisco"], 1, "Le HSM garantit qu'aucune clé de chiffrement maîtresse et aucun code PIN n'apparaît jamais en clair dans la mémoire du serveur.", "C'est le coffre-fort cryptographique de la banque.");
addQ(4, 2, "Que signifie l'acronyme LMK dans la terminologie des HSM bancaires (Thales / Atalla) ?", ["Local Master Key", "Limited Management Kernel", "Line Monitoring Key", "Low Memory Key"], 0, "La LMK est la clé maîtresse locale au HSM. Toutes les autres clés stockées dans les bases de données hôtes sont chiffrées sous la LMK.", "Si la LMK est perdue ou effacée, toutes les clés de la banque deviennent irrécupérables.");
addQ(4, 3, "À quoi sert une clé ZMK (Zone Master Key) échangée entre deux partenaires bancaires ?", ["À chiffrer les e-mails des directeurs", "À transporter en toute sécurité d'autres clés de travail (comme la ZPK) lors des échanges réseau", "À calculer le solde des comptes", "À payer les pénalités d'interchange"], 1, "La ZMK ne chiffre jamais de données directes : elle chiffre uniquement d'autres clés de chiffrement de session.", "Elle est saisie sous forme de composantes séparées par des officiers de sécurité.");
addQ(4, 4, "Quelle clé cryptographique est utilisée pour chiffrer le PIN Block dans les trames d'autorisation entre le terminal et le switch ?", ["La LMK", "La ZPK (Zone PIN Key)", "La CVK", "La clé Wi-Fi"], 1, "La ZPK (Zone PIN Key) est la clé symétrique de travail partagée pour protéger les codes confidentiels en transit.", "Chaque liaison interbancaire dispose de sa propre ZPK.");
addQ(4, 5, "Quel est le rôle de la clé PVK (PIN Verification Key) détenue par la banque émettrice ?", ["Ouvrir la porte blindée de l'agence", "Calculer et vérifier la légitimité du PIN du porteur (via l'Offset de PIN ou l'algorithme IBM 3624)", "Chiffrer le montant de la transaction", "Imprimer le logo sur la carte"], 1, "La PVK sert au HSM émetteur à vérifier que le PIN entré par le porteur correspond bien au compte sans avoir à stocker le PIN en clair.", "L'Offset de PIN est la différence arithmétique entre le PIN naturel et le PIN choisi par le client.");
addQ(4, 6, "Quelle clé est utilisée pour calculer les codes de contrôle CVV1 (piste) et CVV2 (e-commerce) ?", ["La ZMK", "La CVK (Card Verification Key)", "La ZPK", "La LMK"], 1, "La paire de clés CVK (généralement 3DES) génère les 3 chiffres de contrôle à partir du PAN et de la date d'expiration.", "La vérification du CVV2 se fait par commande HSM dédiée (ex: commande Thales CY).");
addQ(4, 7, "Quelle opération mathématique logique est au cœur du format de PIN Block ISO Format 0 (ANSI X9.8) ?", ["L'addition avec retenue", "Le OU Exclusif (XOR bit-à-bit entre le bloc PIN et le bloc PAN)", "La multiplication matricielle", "La division euclidienne"], 1, "Le XOR fusionne le PIN en clair et les 12 chiffres utiles du PAN pour produire un bloc uniforme.", "Cela rend le PIN chiffré dépendant du numéro de carte.");
addQ(4, 8, "Dans un PIN Block ISO Format 0, combien de chiffres de droite du PAN (hors clé de contrôle de Luhn) utilise-t-on pour le masque XOR ?", ["4 chiffres", "12 chiffres", "16 chiffres", "8 chiffres"], 1, "Le masque prend les 12 chiffres situés immédiatement à gauche du dernier chiffre du PAN.", "Les 4 premiers chiffres du masque sont toujours positionnés à '0000'.");
addQ(4, 9, "Qu'est-ce que l'opération de 'Translation de PIN' réalisée par un switch bancaire dans son HSM ?", ["Traduire le code PIN en anglais", "Déchiffrer le PIN Block sous la ZPK entrante (Acquéreur) et le rechiffrer immédiatement sous la ZPK sortante (Émetteur) à l'intérieur du HSM", "Remplacer le code secret par un mot de passe", "Envoyer le PIN au commissariat"], 1, "La translation permet de relayer un paiement sans jamais exposer le PIN en clair sur le serveur applicatif du switch.", "La commande Thales correspondante est la commande 'CA' ou 'CC'.");
addQ(4, 10, "Pourquoi la norme PCI-PIN exige-t-elle le principe de 'Dual Custody / Split Knowledge' pour la saisie des clés maîtresses ?", ["Pour aller deux fois plus vite", "Pour garantir qu'aucun individu isolé ne puisse connaître ou reconstituer seul une clé maîtresse complète", "Pour que le directeur signe deux feuilles de papier", "Pour faire une copie sur clé USB"], 1, "Chaque dépositaire détient une composante mathématique distincte (ex: 2 ou 3 morceaux combinés par XOR).", "Même sous la menace, un employé ne peut pas divulguer la clé complète.");
addQ(4, 11, "Quel algorithme de chiffrement symétrique historique est traditionnellement utilisé pour les clés ZPK et CVK en monétique ?", ["RC4", "Triple-DES (3DES / TDEA à double ou triple longueur)", "MD5", "Blowfish"], 1, "Le Triple-DES (clé de 112 bits ou 168 bits) est le standard historique de référence des HSM bancaires.", "Il est progressivement complété ou remplacé par l'AES (128/256 bits).");
addQ(4, 12, "Quelle taille minimale de clé AES est recommandée par le PCI Security Standards Council pour les nouvelles infrastructures de PIN ?", ["64 bits", "128 bits (ou 256 bits)", "32 bits", "1024 bits"], 1, "L'AES-128 ou AES-256 offre une résistance cryptographique bien supérieure au 3DES contre les attaques par force brute.", "La norme PCI-PIN encourage la migration active vers l'AES.");
addQ(4, 13, "Dans une commande Thales payShield, que réalise la commande hôte 'A0' ?", ["Redémarrer le HSM", "Générer une nouvelle clé aléatoire (ZPK, ZMK ou CVK) chiffrée sous LMK ou ZMK", "Effacer le disque dur", "Imprimer un rapport financier"], 1, "La commande 'A0' (Generate Key) demande au générateur matériel de bruit quantique du HSM de créer une nouvelle clé.", "La clé générée n'est renvoyée à l'hôte que sous forme de cryptogramme chiffré.");
addQ(4, 14, "Que réalise la commande Thales 'CW' ou 'KQ' lors de la réception d'une transaction EMV ?", ["Formater la carte bancaire", "Vérifier la validité de l'ARQC émis par la puce en recalculant le cryptogramme à partir de la clé de dérivation de l'émetteur", "Changer le code postal du client", "Augmenter le solde du compte"], 1, "La commande vérifie que l'ARQC correspond mathématiquement aux données du Tag DE55.", "Si la vérification réussit, elle génère l'ARPC pour la réponse.");
addQ(4, 15, "Qu'est-ce qu'un KCV (Key Check Value) dans la gestion des clés monétiques ?", ["Le prix d'achat du HSM", "Une valeur de contrôle de 6 caractères hexadécimaux obtenue en chiffrant un bloc de zéros avec la clé", "La date de fin de contrat de support", "Le mot de passe de l'administrateur"], 1, "Le KCV permet aux ingénieurs de vérifier qu'ils manipulent la même clé sans jamais dévoiler la clé elle-même.", "Si deux banques ont le même KCV (ex: A1B2C3), elles sont certaines d'avoir la même ZMK.");
addQ(4, 16, "Dans une attaque par force brute sur un code PIN à 4 chiffres (0000 à 9999), combien de combinaisons existent au total ?", ["256 combinaisons", "10 000 combinaisons", "1 000 000 combinaisons", "65 536 combinaisons"], 1, "Un PIN à 4 chiffres compte exactement 10^4 = 10 000 possibilités.", "C'est pourquoi la puce bloque impérativement la carte après 3 faux essais consécutifs.");
addQ(4, 17, "Pourquoi est-il interdit d'utiliser l'algorithme DES simple (56 bits) en production bancaire ?", ["Parce qu'il consomme trop de batterie", "Parce qu'une clé 56 bits peut être cassée par force brute en quelques minutes avec du matériel informatique moderne", "Parce que le gouvernement l'a breveté", "Parce qu'il ne supporte pas les cartes Visa"], 1, "Le DES simple a été cassé dès la fin des années 1990. La norme bancaire impose au minimum le 3DES à double longueur (112 bits effectifs).", "Toute utilisation de DES simple constitue une non-conformité PCI critique.");
addQ(4, 18, "Quelle certification de sécurité matérielle internationale est exigée pour les HSM bancaires par PCI-DSS ?", ["ISO 9001", "FIPS 140-2 Level 3 (ou Level 4)", "CE Mark", "ENERGY STAR"], 1, "Le standard FIPS 140-2 Level 3 garantit une résistance physique éprouvée contre le piratage mécanique, thermique et laser.", "Les HSM bancaires (Thales, Entrust, Utimaco) sont tous certifiés FIPS 140-2 Level 3.");
addQ(4, 19, "Dans le protocole IBM 3624, qu'est-ce que la 'Decimalization Table' utilisée pour le calcul du PIN naturel ?", ["Une table de conversion qui transforme les caractères hexadécimaux (A-F) issus du chiffrement en chiffres décimaux (0-9)", "La liste des prix des cartes bancaires", "La table de conversion de devises", "Le barème fiscal de la banque"], 0, "La table de décimalisation (ex: 0123456789012345) permet d'extraire des chiffres décimaux pour composer un code PIN à 4 chiffres.", "Une mauvaise table de décimalisation sur le HSM provoque des erreurs de PIN à 100% sur les cartes d'une série.");
addQ(4, 20, "Quelle attaque cryptographique célèbre ciblait historiquement les tables de décimalisation des HSM mal configurés ?", ["L'attaque par rebond satellite", "L'attaque par décimalisation (Decimalization Attack)", "L'attaque DDOS", "L'attaque par phishing"], 1, "L'attaque par décimalisation permettait à un attaquant ayant un accès partiel aux commandes de deviner le PIN en modifiant la table chiffre par chiffre.", "Elle a été neutralisée par le durcissement des commandes HSM et l'interdiction des tables arbitraires.");
addQ(4, 21, "Pourquoi la norme PCI-DSS interdit-elle formellement l'utilisation du protocole SSL v3 et TLS 1.0/1.1 pour les flux monétiques ?", ["Ils sont trop rapides", "Ils comportent des vulnérabilités cryptographiques majeures (POODLE, BEAST) permettant d'intercepter les données en transit", "Ils ne fonctionnent pas sur les ordinateurs portables", "Leur nom est trop court"], 1, "Seuls TLS 1.2 et TLS 1.3 avec des suites de chiffrement robustes (Cipher Suites) sont autorisés pour transporter des trames monétiques.", "L'usage de TLS obsolète est un motif de suspension d'agrément bancaire.");
addQ(4, 22, "Qu'est-ce qu'une clé d'injection de terminal (TMK - Terminal Master Key) ?", ["La clé physique pour ouvrir le tiroir caisse", "La clé maîtresse locale injectée dans le TPE pour lui permettre de déchiffrer ses clés de session de travail", "Le numéro de série de l'écran", "Le code postal du magasin"], 1, "La TMK est chargée dans le TPE lors de sa phase d'initialisation en atelier sécurisé.", "Elle permet de télécharger à distance les clés d'acquisition de manière chiffrée.");
addQ(4, 23, "Quel organisme mondial édicte les normes de sécurité physiques et logiques des terminaux de paiement (clavier, lecteur de carte) ?", ["L'ONU", "PCI Security Standards Council (norme PCI-PTS)", "L'Union Postale Universelle", "L'IEEE"], 1, "Le consortium PCI SSC (fondé par Visa, Mastercard, Amex, Discover, JCB) gouverne les normes PCI-PTS (PIN Transaction Security).", "Un terminal non agréé PCI-PTS ne peut pas être déployé dans le réseau bancaire.");
addQ(4, 24, "Qu'est-ce qu'un PIN Block de format ISO-1 ?", ["Un format où le PIN est chiffré sans utiliser le PAN (utilisé lorsque le PAN n'est pas encore connu ou pour les cartes de fidélité)", "Un format réservé aux téléphones Android", "Un format pour les chèques bancaires", "Un format à 8 chiffres obligatoires"], 0, "L'ISO Format 1 utilise un horodatage ou un numéro de transaction aléatoire à la place du PAN.", "Il est utilisé dans certains environnements de porte-monnaie électronique.");
addQ(4, 25, "Dans un schéma de tokenisation bancaire (Apple Pay, Google Pay), que remplace le 'Token' émis par le réseau ?", ["Le nom du propriétaire de l'iPhone", "Le véritable numéro de carte PAN à 16 chiffres par un identifiant virtuel révocable sans changer la carte physique", "Le code guichet de la banque", "Le mot de passe de messagerie"], 1, "La tokenisation protège le PAN : si le marchand se fait pirater sa base, les voleurs ne récupèrent que des tokens inutilisables en dehors du terminal enregistré.", "Le Token Service Provider (TSP) gère la table de correspondance Token <-> PAN.");
addQ(4, 26, "Quel est le principe de l'algorithme 3DES en mode EDE (Encrypt-Decrypt-Encrypt) ?", ["Chiffrer le message trois fois avec la même clé", "Chiffrer avec la clé K1, déchiffrer avec la clé K2, puis chiffrer avec la clé K1 (ou K3)", "Inverser l'ordre des lettres", "Compresser le fichier avant envoi"], 1, "Le mode EDE permet la compatibilité descendante avec le DES simple (si K1=K2=K3) tout en offrant une sécurité de 112 bits avec deux clés différentes.", "C'est la forme standard du 3DES bancaire.");
addQ(4, 27, "Dans un HSM Thales, quel paramètre contrôle la politique de séparation stricte des fonctions et des rôles d'administration ?", ["USER_LIMIT", "HSM Security Policy (Authorized State / Normal State)", "SPEED_MODE", "DEBUG_FLAG"], 1, "En état normal (Normal State), les commandes d'administration sensible sont bloquées.", "Seul le passage en état autorisé (Authorized State) avec les clés physiques de sécurité permet de manipuler les LMK.");
addQ(4, 28, "Pourquoi un journal d'audit de HSM doit-il obligatoirement être horodaté et envoyé en temps réel vers un serveur SIEM sécurisé ?", ["Pour remplir les disques durs", "Pour détecter immédiatement toute tentative d'exécution de commandes non autorisées ou d'attaques par force brute sur les clés", "Pour mesurer la facture d'électricité", "Pour surveiller les horaires de pause du personnel"], 1, "L'auditabilité continue est une exigence PCI-DSS pour garantir la non-répudiation des opérations sur les clés.", "Toute anomalie sur le HSM doit déclencher une alerte de sécurité SOC immédiate.");
addQ(4, 29, "Qu'est-ce qu'une clé DUKPT (Derived Unique Key Per Transaction) largement utilisée sur les TPE mobiles (mPOS) ?", ["Une clé qui ne change jamais pendant 10 ans", "Un système où chaque transaction est chiffrée avec une clé dérivée unique qui s'autodétruit immédiatement après usage", "Une clé partagée par tous les commerçants du pays", "Un mot de passe envoyé par email"], 1, "DUKPT empêche qu'une clé dérobée dans un TPE ne permette de déchiffrer les transactions passées ou futures.", "Le terminal calcule la clé suivante à partir d'un registre matériel et efface la clé précédente.");
addQ(4, 30, "Que se passe-t-il si un capteur de température interne d'un HSM détecte une tentative d'attaque par congélation (Cold Boot Attack) ?", ["Il allume un radiateur", "Il déclenche immédiatement l'effacement de secours des clés maîtresses (Zeroize keys)", "Il met le serveur en veille", "Il envoie un message d'excuse au switch"], 1, "Les attaquants tentent de refroidir les puces à l'azote liquide pour figer la mémoire RAM et lire les clés en clair.", "Les HSM intègrent des capteurs thermiques qui détruisent la mémoire dès que la température chute anormalement." );

// -------------------------------------------------------------
// NIVEAU 5 : CLEARING, COMPENSATION & LITIGES (30 Questions)
// -------------------------------------------------------------
addQ(5, 1, "Quelle est la différence fondamentale entre l'Autorisation (Online) et la Compensation (Clearing) ?", ["L'autorisation est en français et le clearing en anglais", "L'autorisation réserve la provision en temps réel sans transfert d'argent, alors que la compensation calcule les dettes nettes réciproques pour le règlement financier effectif", "L'autorisation est payante et le clearing gratuit", "Le clearing ne concerne que les retraits d'espèces"], 1, "L'autorisation n'est qu'un engagement technique. Le clearing (compensation) est l'échange comptable formel qui déclenche les virements interbancaires.", "Tant que le clearing n'a pas eu lieu, aucune devise n'a quitté la banque.");
addQ(5, 2, "Quel nom porte le système mondial de compensation et de règlement par lots (batch) de Visa ?", ["Visa Direct", "Visa Base II", "Visa Net Instant", "Visa Cash"], 1, "Visa Base II est le moteur historique et mondial de clearing par lots qui traite des centaines de millions de transactions chaque nuit.", "Il structure les flux sous forme d'enregistrements TCE (Transaction Code Enforcement).");
addQ(5, 3, "Quel format de fichier propriétaire Mastercard est le standard international des échanges de clearing ?", ["Format PDF", "Format IPM (Integrated Processing Management)", "Format CSV", "Format Excel XLS"], 1, "Les fichiers Mastercard IPM (messages 1240 / 1442) contiennent l'intégralité des flux de présentation financière et d'impayés.", "Ils sont traités quotidiennement par les modules de back-office monétique.");
addQ(5, 4, "Dans le système de compensation interbancaire régional GIM-UEMOA, quelle institution assure le règlement final des positions nettes ?", ["La Banque Mondiale", "La Banque Centrale des États de l'Afrique de l'Ouest (BCEAO)", "Le Fonds Monétaire International", "Le Trésor Public français"], 1, "Le GIM-UEMOA calcule la balance de compensation multilatérale, et la BCEAO exécute les virements de règlement brut sur les comptes de réserve des banques.", "C'est le principe de la monnaie de banque centrale (Settlement in Central Bank Money).");
addQ(5, 5, "Qu'est-ce que la commission d'interchange (Interchange Fee) dans une transaction par carte de paiement ?", ["Une amende payée par le client", "Une commission financière versée par la banque acquéreuse à la banque émettrice pour rémunérer le risque de crédit et la gestion du compte porteur", "Une taxe sur la valeur ajoutée", "Le coût de location du terminal"], 1, "L'interchange est prélevée lors de la compensation : l'acquéreur reçoit le montant net de la part de l'émetteur.", "Elle compense les coûts de garantie de paiement assumés par l'émetteur.");
addQ(5, 6, "Quelle écriture comptable est passée dans le Core Banking (CBS) lors de l'intégration d'un fichier de clearing de retrait GAB externe pour un client de la banque ?", ["Débit du compte client / Crédit du compte de compensation Scheme (Nostro Visa/GIM)", "Crédit du compte client / Débit de la caisse agence", "Débit des capitaux propres / Crédit des impôts", "Aucune écriture"], 0, "La banque débite définitivement son client et crédite le compte miroir du switch qui a avancé les fonds.", "Cette écriture matérialise le dénouement financier de l'opération.");
addQ(5, 7, "Dans la procédure de litige monétique, qu'est-ce qu'un 'First Chargeback' émis par la banque émettrice ?", ["Un compliment envoyé au commerçant", "La contestation formelle et le débit d'office de l'acquéreur pour rembourser le porteur victime d'une anomalie ou d'une fraude", "Une demande de relevé bancaire", "Une annulation de carte de crédit"], 1, "Le First Chargeback transfère la charge financière du litige de l'émetteur vers l'acquéreur via le switch.", "L'acquéreur dispose d'un délai réglementaire pour contester ou accepter.");
addQ(5, 8, "Dans quel délai calendaire maximal (selon les règles de Visa et Mastercard) un porteur peut-il généralement contester un débit frauduleux ?", ["24 heures", "120 jours calendaires à compter de la date de transaction ou de livraison promise", "10 ans", "3 jours ouvrés"], 1, "Le délai standard mondial de recevabilité d'un litige client est de 120 jours.", "Passé ce délai, la banque émettrice perd tout droit de recours auprès du switch.");
addQ(5, 9, "Comment appelle-t-on la réponse formelle de la banque acquéreuse qui fournit les preuves que la transaction était légitime ?", ["Le Pardon", "La Représentation (Re-presentment / Second Presentment)", "L'Amnistie", "Le Quitus"], 1, "La Représentation permet à l'acquéreur de redébiter l'émetteur en joignant les justificatifs irréfutables (bon de livraison, ticket EMV signé, log GAB).", "Si l'émetteur est convaincu, le dossier est clos.");
addQ(5, 10, "Si l'émetteur refuse la Représentation et que l'acquéreur maintient sa position, quelle étape ultime tranche le dossier ?", ["Le tribunal de commerce local", "La commission d'arbitrage officielle du Scheme (Visa / Mastercard Dispute Resolution)", "Le tirage au sort", "Le vote des internautes"], 1, "Les juristes de Visa ou Mastercard étudient les preuves techniques et rendent un verdict sans appel.", "La partie perdante supporte les fonds plus 500 $ de frais de dossier.");
addQ(5, 11, "Quel Reason Code Visa identifie couramment une contestation pour transaction frauduleuse par carte contrefaite ?", ["Reason Code 10.4 (Other Fraud - Card-Absent / Counterfeit)", "Reason Code 00.1", "Reason Code 99.9", "Reason Code 13.1"], 0, "Le code 10.4 est le motif maître utilisé en cas d'utilisation frauduleuse de données de carte clonées.", "L'acquéreur doit prouver la présence d'une puce EMV valide pour s'en défendre.");
addQ(5, 12, "Quel Reason Code Mastercard correspond à la non-délivrance des marchandises ou services achetés ?", ["Reason Code 4853 (Cardholder Dispute - Defective/Not as Described/Services Not Rendered)", "Reason Code 4808", "Reason Code 4837", "Reason Code 4849"], 0, "Le code 4853 régit les litiges où le commerçant n'a pas livré le bien ou fait faillite avant prestation.", "Le porteur doit prouver qu'il a tenté de résoudre le litige à l'amiable avec le marchand.");
addQ(5, 13, "Pourquoi le cryptogramme TC (Transaction Certificate) constitue-t-il la meilleure défense d'un acquéreur face à un chargeback de fraude ?", ["Parce qu'il prouve que le client est riche", "Parce qu'il démontre mathématiquement que la véritable puce physique de la carte a généré le cryptogramme sur un terminal sécurisé", "Parce qu'il contient l'empreinte digitale du client", "Parce qu'il est imprimé en lettres d'or"], 1, "Le TC prouve qu'il n'y a pas eu de clonage sur piste magnétique : la responsabilité de la fraude bascule sur l'émetteur (Liability Shift).", "Un dossier de défense sans TC en environnement puce est quasi systématiquement perdu.");
addQ(5, 14, "Qu'est-ce qu'un compte Nostro dans la comptabilité des opérations de compensation internationale ?", ["Le compte de notre banque ouvert dans les livres d'une banque correspondante ou du switch de compensation", "Le compte d'épargne du directeur", "La caisse des menues dépenses", "Le compte des salaires du personnel"], 0, "Nostro ('Notre compte chez vous') retrace les avoirs de la banque auprès de Visa, Mastercard ou de la banque centrale pour dénouer les flux.", "Vostro ('Votre compte chez nous') retrace l'inverse.");
addQ(5, 15, "Que désigne l'écart de rapprochement (Reconciliation Break) entre les autorisations temps réel et les fichiers de clearing ?", ["Une pause café prise par l'opérateur", "Une divergence de montants, de devises ou une transaction autorisée qui n'apparaît jamais dans le fichier de compensation après plusieurs jours", "Une panne de souris d'ordinateur", "Un changement de mot de passe"], 1, "Les suspens monétiques doivent être lettrés au centime près chaque matin pour éviter les fuites de trésorerie.", "Une transaction non présentée expire au bout de 7 à 10 jours et la provision réservée doit être restituée au client.");
addQ(5, 16, "Dans un flux de compensation multi-devises (ex: paiement en USD par une carte libellée en FCFA), qui applique le taux de change de conversion ?", ["Le chauffeur de taxi", "Le Scheme international (Visa ou Mastercard) selon son cours de gros du jour de traitement de clearing", "Le commerçant sur sa calculatrice", "Le consulat"], 1, "Le switch convertit le montant de transaction en devise de compensation (Settlement Currency) et facture des frais de conversion de change.", "L'émetteur convertit ensuite le montant de règlement dans la devise du compte porteur.");
addQ(5, 17, "Pourquoi les batchs de clearing monétique doivent-ils être injectés dans le Core Banking avant l'heure limite du Cut-Off comptable ?", ["Pour que les employés partent plus tôt", "Pour que les positions nettes soient intégrées dans l'arrêté journalier (EOD) et que les soldes des comptes soient certifiés conformes pour l'ouverture du lendemain", "Pour économiser du papier", "Pour libérer les lignes téléphoniques"], 1, "Tout retard d'injection du clearing bloque la chaîne batch EOD de la banque et retarde l'ouverture des agences au public à 07h30.", "C'est un engagement de service (SLA) critique sous astreinte.");
addQ(5, 18, "Qu'est-ce que la procédure de 'Pre-Arbitration' dans le règlement des litiges Visa/Mastercard ?", ["Un match amical de football", "Une ultime phase de négociation amiable encadrée par le portail du switch avant de soumettre formellement le dossier aux juristes de l'arbitrage", "Une demande de prêt bancaire", "Un formulaire fiscal"], 1, "Le pré-arbitrage évite les frais de pénalité de 500 $ en donnant une dernière chance à la banque adverse d'accepter le litige à la vue de nouveaux éléments.", "90% des dossiers se règlent durant cette phase.");
addQ(5, 19, "Dans le cadre de la réconciliation monétique ATM, que signifie un solde comptable de caisse 'Excédentaire' (Cash Over) ?", ["Il manque de l'argent dans le coffre", "Le montant physique de billets compté dans le coffre est supérieur au solde théorique calculé par les débits du système", "Tous les billets ont été volés", "Le distributeur a refusé de démarrer"], 1, "L'excédent (Over) arrive souvent lorsqu'un client a vu sa transaction échouer mécaniquement après le débit ou en cas de billets non retirés.", "Cet excédent sert à rembourser les réclamations porteurs légitimes enregistrées sur cet automate.");
addQ(5, 20, "Que signifie à l'inverse un solde de caisse GAB 'Déficitaire' (Cash Short) ?", ["Le coffre contient moins de billets que ce que prévoyaient les écritures comptables", "Le coffre est rempli de faux billets", "La banque a doublé ses bénéfices", "Le client a rendu de l'argent"], 0, "Le déficit (Short) traduit une anomalie mécanique où l'automate a délivré plus de billets que comptabilisé, ou un problème lors du chargement des fonds par les convoyeurs.", "Il donne lieu à une enquête contradictoire d'audit interne.");
addQ(5, 21, "Quel enregistrement dans un fichier Visa Base II contient les détails de la transaction financière d'un achat porteur ?", ["L'enregistrement TCR 0 (Transaction Component Record 0 / Transaction Code 05)", "L'enregistrement de fin de fichier EOF", "L'en-tête de bande magnétique", "Le mot de passe de session"], 0, "Le TCR 0 porte le PAN, le montant, la devise, le code autorisation et la date de transaction.", "Des TCR supplémentaires (TCR 1, 5, 7) apportent les données de devise et les tags EMV.");
addQ(5, 22, "Comment appelle-t-on le compte comptable d'attente servant à équilibrer les écritures en attendant le lettrage définitif du fichier de clearing ?", ["Le compte de résultat net", "Le compte de suspense monétique (ou compte de passerelle de compensation)", "Le compte de réserve légale", "Le compte courant d'associé"], 1, "Le compte de suspense permet d'enregistrer l'autorisation immédiatement et d'attendre la ligne de compensation pour solder l'écart.", "Un solde de suspense anormalement élevé alerte sur un dysfonctionnement de clearing.");
addQ(5, 23, "Dans un litige monétique e-commerce, pourquoi le protocole 3D-Secure (3DS / OTP SMS / App biométrique) protège-t-il le commerçant contre le chargeback de fraude ?", ["Il oblige le commerçant à livrer gratuitement", "L'authentification forte réussie du porteur opère un transfert de responsabilité (Liability Shift) vers la banque émettrice qui a authentifié son client", "Il supprime la TVA", "Il rend le paiement instantané"], 1, "Grâce à 3DS (Verified by Visa / Mastercard Identity Check), le commerçant est garanti d'être payé même si le porteur prétend ne pas avoir fait l'achat.", "La banque émettrice assume le risque de fraude si elle a mal validé l'OTP.");
addQ(5, 24, "Qu'est-ce qu'une transaction 'Draft Clearing' (présentation tardive de clearing) reçue 25 jours après l'achat ?", ["Une transaction refusée par le client", "Une transaction commerciale transmise tardivement par l'acquéreur au switch alors que l'empreinte d'autorisation temps réel a déjà expiré", "Une transaction sur un compte fermé", "Un chèque en bois"], 1, "Même si l'autorisation a expiré sur le compte du client, le commerçant a légalement le droit de réclamer son dû pendant plusieurs semaines.", "La banque émettrice doit débiter le compte client même si le solde est devenu négatif.");
addQ(5, 25, "Que se passe-t-il si un compte client n'a plus les fonds nécessaires lors de l'arrivée du fichier de clearing d'une transaction préalablement autorisée avec succès ?", ["Le switch annule la transaction", "La banque émettrice débite le compte client d'office, le plaçant en découvert non autorisé (solde débiteur forcé), car elle a déjà engagé sa responsabilité irrévocable lors de l'autorisation", "Le commerçant doit rembourser la banque", "La police est prévenue"], 1, "L'autorisation initiale engage irrévocablement la banque à payer le commerçant.", "La banque supporte le risque de recouvrement auprès de son client.");
addQ(5, 26, "Dans la norme ISO 20022 appelée à moderniser les flux de compensation mondiaux, quel est le format syntaxique des messages financiers ?", ["Fichiers texte à colonnes fixes", "Messages structurés en XML (balises) ou JSON avec validation par schéma XSD", "Poinçons sur cartes carton", "Signaux sonores en code Morse"], 1, "ISO 20022 remplace la syntaxe compacte ISO 8583 par des messages XML riches (ex: pain, pacs, camt) permettant une traçabilité documentaire sans faille.", "C'est la norme moderne adoptée par SWIFT et les banques centrales.");
addQ(5, 27, "Dans un fichier de compensation Mastercard IPM, quelle valeur de MTI identifie un message de présentation financière initiale (First Presentment) ?", ["MTI 1240", "MTI 0200", "MTI 0800", "MTI 1442"], 0, "Le message 1240 dans l'IPM est le format standard de présentation de débit d'un achat commerçant.", "Le message 1442 identifie les messages de chargeback et de litige.");
addQ(5, 28, "À quoi sert le numéro ARN (Acquirer Reference Number) à 23 chiffres attribué à chaque transaction lors de la compensation ?", ["À joindre le porteur au téléphone", "À identifier et tracer de manière absolument unique et universelle l'opération dans les bases mondiales de Visa/Mastercard pour les litiges", "À crypter le code secret", "À calculer la distance géographique"], 1, "L'ARN est le numéro d'immatriculation juridique de la transaction dans le clearing international.", "C'est la référence que les banques se transmettent obligatoirement lors de l'ouverture d'un chargeback.");
